import assert from "node:assert/strict";
import { test } from "node:test";
import { groupBy, unique } from "../src/collections.ts";

test("grader: groupBy", () => {
  const g = groupBy([1, 2, 3, 4], (n) => n % 2);
  assert.ok(g instanceof Map);
  assert.deepEqual([...g.keys()], [1, 0]);
  assert.deepEqual(g.get(1), [1, 3]);
  assert.deepEqual(g.get(0), [2, 4]);
  assert.equal(groupBy([], (n: number) => n).size, 0);
  assert.deepEqual(unique([1, 1, 2]), [1, 2]);
});

